pub fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    let mut best: Option<Vec<char>> = None;
    let mut best_len = 0;

    for s in strings.into_iter() {
        let len = s.len();
        // Update if this is the first element or strictly longer than the current best
        if best.is_none() || len > best_len {
            best_len = len;
            best = Some(s);
        }
    }

    best
}

